// ─────────────────────────────────────────────────────────────────────────────
// NO-EDGE VERDICTS (round 41 — the no-noise audit; simulator-locked). Deliberation
// is DECLARED only where two managers' stewarded evidence genuinely conflicts over
// a recurring decision (the round-36 bar: something to ARGUE + a live emitter).
// Managers with NO deliberative seat are listed HONESTLY with the why — an edge
// minted for its own sake would be noise, not teamwork:
//   · asset_manager — no conflicting evidence exists between asset_manager and a
//     peer: its stewarded ledger (ai_video_projects) records renders, not dollars
//     (the table has no cost column), the media-spend telemetry it would need to
//     argue a budget (vendor_usage_tracking, platform rates) is data_steward-
//     stewarded platform cost accounting, and render distribution is already a
//     governed HANDOFF with one obvious action (creative_distribution /
//     listing_launch_play — stage, cut, distribute, promote; nothing to argue).
//     An edge would be noise until a tenant-facing media budget with an
//     asset-stewarded cost ledger exists.
//   · cron_manager — no conflicting evidence exists between cron_manager and a
//     peer: its evidence (approval-SLA telemetry, loop health, the self-heal
//     ledger) states operational FACTS no peer's ledger disputes — an aged queue
//     has one obvious action (clear it or surface the blocker), which is exactly
//     the approval_queue_slo HANDOFF its live sweep already emits. Its grounded
//     fact loader stays registered (loadCronManagerFacts) so it can take a seat
//     the day a real dispute emerges; a manufactured seat today would be noise.
// Candidates evaluated and REJECTED the same way (documented, never silently
// dropped):
//   · sphere_of_influence × finance_manager on gift/QBR budgets — client_gifts.cost
//     records spend AFTER the human picks the gift, and Finance stewards no
//     gift-budget ledger to argue against, so the two seats hold no conflicting
//     evidence about gifting. The Sphere's genuine money seam is the referral fee
//     (referral_fee_economics above), where real terms land on the commission rail.
// ─────────────────────────────────────────────────────────────────────────────

/** Every collaboration domain a manager co-manages (governance surface). Pure. */
export function collaborationsFor(manager: ManagerKey): CollaborationDomain[] {
  return Object.values(MANAGER_COLLABORATIONS).filter((d) => d.managers.includes(manager))
}

/**
 * Is from → to a DECLARED cross-management edge? True only when both are real,
 * distinct managers sharing a collaboration domain (the named one when
 * domainKey is given, any one otherwise). The referral handler enforces this —
 * an undeclared referral is refused on the bus, honestly, with the reason.
 */
export function canRefer(from: string, to: string, domainKey?: string): boolean {
  if (!(from in MANAGERS) || !(to in MANAGERS) || from === to) return false
  const domains = domainKey
    ? (MANAGER_COLLABORATIONS[domainKey] ? [MANAGER_COLLABORATIONS[domainKey]] : [])
    : Object.values(MANAGER_COLLABORATIONS)
  return domains.some((d) => d.managers.includes(from as ManagerKey) && d.managers.includes(to as ManagerKey))
}

